<h1 class="text-3xl font-bold mb-6"><?=htmlspecialchars($title)?></h1><?php if($resource==='categories'):?><form method="post" class="flex gap-3 mb-6"><?=$csrf->field()?><input class="bg-slate-800 p-3 rounded" name="name" placeholder="Nombre" required><select name="type" class="bg-slate-800 p-3 rounded"><option value="live">Canales</option><option value="movie">Películas</option><option value="series">Series</option></select><button class="bg-cyan-600 px-5 rounded">Añadir</button></form><?php endif?><div class="space-y-2"><?php foreach($items as $item):?><article class="bg-slate-900 border border-slate-800 rounded p-3 overflow-auto"><pre><?=htmlspecialchars(json_encode($item,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre><?php if($resource==='servers'):?><div class="flex gap-2 mt-3"><?php foreach(['online'=>'Activar','draining'=>'Drenar','maintenance'=>'Mantenimiento'] as $mode=>$label):?><form method="post" action="/servers/mode"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$item['id']?>"><input type="hidden" name="mode" value="<?=$mode?>"><button class="bg-slate-700 px-3 py-1 rounded"><?=$label?></button></form><?php endforeach?></div><?php endif?></article><?php endforeach?></div>
